package project.init.account.repository;import jakarta.persistence.criteria.Join;import jakarta.persistence.criteria.JoinType;import jakarta.persistence.criteria.Predicate;import org.springframework.data.jpa.domain.Specification;import org.springframework.util.CollectionUtils;import org.springframework.util.ObjectUtils;import project.init.account.domain.entity.Account;import project.init.account.domain.entity.AccountRole;import project.init.account.domain.req.FilterAccountReq;import java.util.ArrayList;import java.util.List;public class AccountSpecification {    public static Specification<Account> filter(FilterAccountReq req) {        return (root, query, cb) -> {            List<Predicate> predicates = new ArrayList<>();            if (!ObjectUtils.isEmpty(req.getStatus())) {                predicates.add(cb.equal(root.get("accountStatus"), req.getStatus()));            }            if (!ObjectUtils.isEmpty(req.getAccountCode())) {                predicates.add(cb.like(cb.upper(root.get("accountCode")), "%" + req.getAccountCode().toUpperCase() + "%"));            }            if (!CollectionUtils.isEmpty(req.getRoles())) {                Join<Account, AccountRole> roleJoin = root.join("roles", JoinType.INNER);                predicates.add(roleJoin.get("code").in(req.getRoles()));            }            query.orderBy(cb.desc(root.get("createdAt")));            return cb.and(predicates.toArray(new Predicate[0]));        };    }}/** - Dynamic Query (truy vấn động) là kiểu truy vấn mà các điều kiện lọc được xây dựng trong lúc runtime (chạy chương trình) thay vì được viết cố định (hardcoded).* */